<?php
require_once __DIR__.'/../config/auth.php'; require_once __DIR__.'/../config/admin-schema.php'; require_login(); ensure_admin_tables(); header('Content-Type: application/json; charset=utf-8');
$pdo=db();$u=current_user();
if($_SERVER['REQUEST_METHOD']==='GET'){$fy=(int)($_GET['fy']??0);if(!$fy){echo json_encode(['ok'=>false,'error'=>'Invalid fiscal year']);exit;}$q=$pdo->prepare('SELECT deadline_date FROM submission_deadlines WHERE fy=?');$q->execute([$fy]);$date=$q->fetchColumn();$late=$date && $date<date('Y-m-d');$status='';if($late){$q=$pdo->prepare('SELECT status FROM late_submission_requests WHERE dept_code=? AND fy=? ORDER BY id DESC LIMIT 1');$q->execute([$u['dept_code'],$fy]);$status=(string)$q->fetchColumn();}echo json_encode(['ok'=>true,'late'=>(bool)$late,'deadline'=>$date?:null,'approved'=>$status==='approved','pending'=>$status==='pending']);exit;}
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'error'=>'Method not allowed']);exit;}$fy=(int)($_POST['fy']??0);$reason=trim((string)($_POST['reason']??''));if(!$fy||mb_strlen($reason)<10){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Please provide a reason of at least 10 characters.']);exit;}$q=$pdo->prepare('SELECT deadline_date FROM submission_deadlines WHERE fy=?');$q->execute([$fy]);$date=$q->fetchColumn();if(!$date||$date>=date('Y-m-d')){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'A late-submission request is only available after the deadline.']);exit;}$q=$pdo->prepare("SELECT id FROM late_submission_requests WHERE dept_code=? AND fy=? AND status='pending' LIMIT 1");$q->execute([$u['dept_code'],$fy]);if($q->fetch()){echo json_encode(['ok'=>false,'error'=>'Your department already has a pending request.']);exit;}$pdo->prepare("INSERT INTO late_submission_requests(user_id,dept_code,fy,reason,status) VALUES(?,?,?,?,'pending')")->execute([(int)$u['id'],$u['dept_code'],$fy,$reason]);echo json_encode(['ok'=>true,'message'=>'Your request was sent to the Procurement Unit for review.']);
